const article = document.querySelector('.main-article');
const aside = document.querySelector('.side-panel');
const multiCol = document.getElementById('multi-column-section');
if (!article || !aside || !multiCol) return false;

const isEnabled = document.documentElement.classList.contains('ai4a11y-reflow');
if (!isEnabled) {
  const artStyle = window.getComputedStyle(article);
  const asideStyle = window.getComputedStyle(aside);
  const colStyle = window.getComputedStyle(multiCol);
  return artStyle.float === 'left' && asideStyle.float === 'right' && colStyle.columnCount === '3';
}

const artStyle = window.getComputedStyle(article);
const asideStyle = window.getComputedStyle(aside);
const colStyle = window.getComputedStyle(multiCol);

if (artStyle.float !== 'none' || asideStyle.float !== 'none') return false;
if (colStyle.columnCount !== 'auto') return false;

const artRect = article.getBoundingClientRect();
const asideRect = aside.getBoundingClientRect();
return asideRect.top >= artRect.bottom - 5;

const grid = document.getElementById('wide-grid');
if (!grid) return false;

const isEnabled = document.documentElement.classList.contains('ai4a11y-reflow');
const cards = grid.querySelectorAll('.grid-card');
if (cards.length < 2) return false;

if (!isEnabled) {
  return !grid.classList.contains('ai4a11y-reflow-grid');
}

if (!grid.classList.contains('ai4a11y-reflow-grid')) return false;
const c0 = cards[0].getBoundingClientRect();
const c1 = cards[1].getBoundingClientRect();
return c1.top >= c0.bottom - 5 && Math.abs(c0.left - c1.left) < 5;

const squeezed = document.getElementById('squeezed-container');
const text = document.getElementById('squeezed-text');
const img = document.getElementById('wide-image');
if (!squeezed || !text || !img) return false;

const isEnabled = document.documentElement.classList.contains('ai4a11y-reflow');
if (!isEnabled) {
  const sStyle = window.getComputedStyle(squeezed);
  return sStyle.flexWrap === 'nowrap' && !squeezed.classList.contains('ai4a11y-reflow-wrap');
}

if (!squeezed.classList.contains('ai4a11y-reflow-wrap')) return false;
const sStyle = window.getComputedStyle(squeezed);
if (sStyle.flexWrap !== 'wrap') return false;

const imgRect = img.getBoundingClientRect();
const bodyRect = document.body.getBoundingClientRect();
return imgRect.width <= bodyRect.width + 1;

const btnSave = document.getElementById('btn-save');
const btnShare = document.getElementById('btn-share');
if (!btnSave || !btnShare) return false;

for (const btn of [btnSave, btnShare]) {
  const r = btn.getBoundingClientRect();
  if (r.width < 24 || r.height < 24) return false;
}

btnSave.focus();
if (document.activeElement !== btnSave) return false;
const style = window.getComputedStyle(btnSave);
const hasOutline = parseFloat(style.outlineWidth) >= 2 || style.outlineStyle !== 'none';
btnSave.click();
btnSave.blur();

return hasOutline;

const toolbar = document.getElementById('toolbar');
if (!toolbar) return false;

const isEnabled = document.documentElement.classList.contains('ai4a11y-reflow');
if (isEnabled) {
  return !toolbar.classList.contains('ai4a11y-reflow-wrap');
}
return true;
